    slug: "building-first-web-portfolio",
    title: "Building your first web developer portfolio that actually gets read",
    excerpt: "Your portfolio is not a gallery. It is a conversation with a future employer.",
    category: "Career",
    author: "Cyber Elias Academy",
    role: "Team CEA",
    date: "2026-07-22",
    readingTime: "10 min",
